function md_fence(line,   m) {
    if (_inf) {
        if (match(line, /^ {0,3}(```+|~~~+)[ \t]*$/)) { m = substr(line, RSTART, RLENGTH); gsub(/[ \t]/, "", m); if (substr(m,1,1)==_fc && length(m) >= _fl) _inf = 0 }
